const {deviceState,syncDevice}=require('../../utils/page')
const api=require('./practiceService')

const publicParam=(value,max=180)=>String(value||'').replace(/[\u0000-\u001f\u007f]/g,' ').trim().slice(0,max)
const answered=draft=>draft?draft.questionIds.filter(id=>Array.isArray(draft.answers[id])&&draft.answers[id].length).length:0
const countOptions=available=>{const capped=Math.min(50,available);return[...new Set([1,5,10,20,30,40,50,capped].filter(value=>Number.isInteger(value)&&value>0&&value<=capped))].sort((a,b)=>a-b).map(value=>({value,label:value+' 题'}))}
const errorMessages={auth_required:'登录已过期，答案仍保存在本机。请重新登录后继续。',authentication_required:'请登录后开始选择题练习。',practice_scope_changed:'账号已变化，请重新打开选择题练习。',practice_storage_full:'本机空间不足，答案尚未保存。请释放空间后重试。',network_timeout:'请求超时，答案已保留，请重试。',network_error:'网络连接失败，答案已保留，请重试。',network_domain_blocked:'当前版本无法连接练习服务，请更新小程序后重试。',network_tls_error:'安全连接未能建立，请稍后重试。',curriculum_practice_release_mismatch:'题库版本已更新，答案仍保存在本机。请返回重新开始。',curriculum_practice_session_binding_mismatch:'练习绑定已失效，答案仍保存在本机。请返回重新开始。',curriculum_practice_question_binding_mismatch:'题目与当前练习不匹配，请返回重新开始。',curriculum_practice_idempotency_mismatch:'提交内容已变化，答案仍保存在本机。请修改答案后重新提交。',curriculum_practice_session_immutable:'这次练习已经提交，请从最近学习结果中查看。',curriculum_practice_session_not_found:'未找到这次练习，可能已退出账号或记录已失效。',curriculum_practice_answers_incomplete:'仍有未作答题目，请确认后再提交。',curriculum_practice_question_not_found:'这道题暂未开放，请返回重新选择。',curriculum_practice_source_unavailable:'当前题原图暂时不可用，请稍后重试。',curriculum_practice_release_unavailable:'选择题题库暂时不可用，请稍后重试。',curriculum_practice_storage_unavailable:'练习记录暂时无法保存，请稍后重试。'}
const errorText=error=>{const code=String(error?.code||'');if(errorMessages[code])return errorMessages[code];if(Number(error?.statusCode)===401)return errorMessages.auth_required;if(Number(error?.statusCode)>=500||code.startsWith('curriculum_practice_'))return'选择题练习暂时无法继续，答案已保留，请重试。';const message=String(error?.message||'').trim();return/[\u4e00-\u9fff]/.test(message)&&!/https?:|stack|provider|api[ _-]?key/i.test(message)?message.slice(0,200):'选择题练习暂时无法继续，答案已保留，请重试。'}
const sourceLabel=(question,route)=>{const year=String(question?.paperId||'').match(/(?:19|20)\d{2}/)?.[0];return[year,route?.label||'AP MCQ'].filter(Boolean).join(' · ')}

Page({
 data:deviceState({phase:'setup',loading:true,busy:false,questionLoading:false,error:'',status:'',authRequired:false,routeId:'',topicId:'',routeOptions:[],routeIndex:0,topicOptions:[],topicIndex:0,count:10,countOptions:[],availableCount:0,history:[],resumeVisible:false,resumeLabel:'',sessionId:'',index:0,total:0,answeredCount:0,question:null,selectedOptions:[],selectionCount:0,result:null,currentResult:null}),
 onLoad(options={}){this.__disposed=false;this.__catalogRequest=0;this.__questionRequest=0;this.__operationRequest=0;this.__cache=new Map();this.__scope=api.scope();this.__initial={routeId:publicParam(options.routeId),topicId:publicParam(options.topicId),sessionId:publicParam(options.sessionId)};return this.loadCatalog()},
 onShow(){syncDevice(this);const next=api.scope();if(this.__scope&&(next.owner!==this.__scope.owner||next.epoch!==this.__scope.epoch)){this.__scope=next;this.__session=null;this.__draft=null;this.__cache?.clear();this.setData({phase:'setup',sessionId:'',question:null,result:null,error:'账号已变化，请重新选择练习。',authRequired:!api.current(next)});this.syncResume()}},
 onResize(){syncDevice(this)},
 onUnload(){this.__disposed=true;this.__catalogRequest++;this.__questionRequest++;this.__operationRequest++},
 selectedRoute(){return this.__catalog?.routes.find(item=>item.id===this.data.routeId)},
 selectedTopic(){return this.selectedRoute()?.topics.find(item=>item.id===this.data.topicId)},
 active(){return!this.__disposed&&api.current(this.__scope)},
 async loadCatalog(){
  const request=++this.__catalogRequest;this.setData({loading:true,error:''})
  try{
   const catalog=await api.fetchCatalog();if(this.__disposed||request!==this.__catalogRequest)return false
   const routes=catalog.routes.filter(route=>route.questionCount>0);if(!routes.length)throw Error('当前没有已开放的 AP 选择题练习。')
   this.__catalog={...catalog,routes};const requested=routes.find(item=>item.id===this.__initial.routeId),route=requested||routes[0],topic=route.topics.find(item=>item.id===this.__initial.topicId),routeOptions=routes.map(item=>({value:item.id,label:item.label,count:item.questionCount})),topicOptions=[{value:'',label:'全部章节',questionCount:route.questionCount},...route.topics.filter(item=>item.questionCount>0).map(item=>({value:item.id,label:item.label,questionCount:item.questionCount}))],available=topic?.questionCount||route.questionCount,counts=countOptions(available),count=counts.some(item=>item.value===10)?10:counts.at(-1)?.value||1
   this.setData({routeId:route.id,topicId:topic?.id||'',routeOptions,routeIndex:routeOptions.findIndex(item=>item.value===route.id),topicOptions,topicIndex:Math.max(0,topicOptions.findIndex(item=>item.value===(topic?.id||''))),availableCount:available,count,countOptions:counts,authRequired:!api.current(this.__scope)})
   this.syncResume();await this.loadHistory()
   if(this.__initial.sessionId&&this.active())await this.restoreSession(this.__initial.sessionId)
   return true
  }catch(error){if(!this.__disposed&&request===this.__catalogRequest)this.setData({error:errorText(error)}) ;return false}
  finally{if(!this.__disposed&&request===this.__catalogRequest)this.setData({loading:false})}
 },
 async loadHistory(){if(!this.active())return this.setData({history:[]});try{const sessions=await api.fetchHistory(this.__scope);if(!this.active())return;const labels=Object.fromEntries(this.__catalog.routes.map(route=>[route.id,route.label]));this.setData({history:sessions.filter(session=>session.status==='submitted').slice(0,5).map(session=>({id:session.id,label:labels[session.routeId]||session.routeId,score:session.result.score,maxScore:session.result.maxScore,submittedAt:session.submittedAt}))})}catch{if(!this.__disposed)this.setData({history:[]})}},
 syncResume(){const recent=api.current(this.__scope)?api.recentDraft(this.__scope,this.data.routeId):null;if(!recent)return this.setData({resumeVisible:false,resumeLabel:''});this.__recent=recent;this.setData({resumeVisible:true,resumeLabel:`${recent.routeLabel||'选择题练习'}${recent.topicLabel?' · '+recent.topicLabel:''} · ${answered(recent)} / ${recent.questionIds.length} 已作答`})},
 applyRoute(routeId,topicId=''){const route=this.__catalog?.routes.find(item=>item.id===routeId);if(!route)return;const topic=route.topics.find(item=>item.id===topicId),topicOptions=[{value:'',label:'全部章节',questionCount:route.questionCount},...route.topics.filter(item=>item.questionCount>0).map(item=>({value:item.id,label:item.label,questionCount:item.questionCount}))],available=topic?.questionCount||route.questionCount,counts=countOptions(available),count=counts.some(item=>item.value===10)?10:counts.at(-1)?.value||1;this.setData({routeId:route.id,routeIndex:this.data.routeOptions.findIndex(item=>item.value===route.id),topicId:topic?.id||'',topicOptions,topicIndex:Math.max(0,topicOptions.findIndex(item=>item.value===(topic?.id||''))),availableCount:available,count,countOptions:counts,error:''});this.syncResume()},
 chooseRoute(event){if(this.data.loading||this.data.busy)return;const option=this.data.routeOptions[Number(event.detail?.value)];if(option)this.applyRoute(option.value)},
 chooseTopic(event){if(this.data.loading||this.data.busy)return;const option=this.data.topicOptions[Number(event.detail?.value)];if(option)this.applyRoute(this.data.routeId,option.value)},
 chooseCount(event){const count=Number(event.currentTarget?.dataset?.count);if(!this.data.busy&&this.data.countOptions.some(item=>item.value===count))this.setData({count,error:''})},
 async start(){
  if(this.data.loading||this.data.busy)return false;if(!this.active()){this.setData({authRequired:true,error:'请登录后开始选择题练习。'});return false}
  const route=this.selectedRoute(),topic=this.selectedTopic(),scope=this.__scope,generation=++this.__operationRequest;this.setData({busy:true,error:'',status:'正在建立练习…'})
  try{const session=await api.createSession({routeId:this.data.routeId,...(this.data.topicId?{topicId:this.data.topicId}:{}),count:this.data.count},scope);if(this.__disposed||generation!==this.__operationRequest||!this.active())return false;const draft=api.createDraft(session,scope,{routeLabel:route?.label||'',topicLabel:topic?.label||''});api.saveDraft(draft,scope);this.enterSession(session,draft);await this.loadQuestion(0);return true}catch(error){if(!this.__disposed&&generation===this.__operationRequest)this.setData({error:errorText(error),authRequired:Number(error?.statusCode)===401,status:''});return false}finally{if(!this.__disposed&&generation===this.__operationRequest)this.setData({busy:false})}
 },
 enterSession(session,draft){this.__session=session;this.__draft=draft;this.__cache.clear();this.setData({phase:session.status==='submitted'?'result':'practice',sessionId:session.id,index:draft.index||0,total:session.questionIds.length,answeredCount:answered(draft),result:session.result||draft.result||null,error:'',status:'',authRequired:false})},
 async restoreSession(sessionId){
  if(this.data.busy||!this.active())return false;const generation=++this.__operationRequest;this.setData({busy:true,error:'',status:'正在恢复练习…'})
  try{const session=await api.getSession(sessionId,this.__scope);if(this.__disposed||generation!==this.__operationRequest||!this.active())return false;let draft=api.readDraft(session.id,this.__scope);if(!draft||draft.questionIds.join('|')!==session.questionIds.join('|'))draft=api.createDraft(session,this.__scope,{routeLabel:this.__catalog.routes.find(item=>item.id===session.routeId)?.label||session.routeId,topicLabel:''});if(session.status==='submitted'){draft.status='submitted';draft.answers=Object.fromEntries(session.answers.filter(answer=>!answer.unanswered).map(answer=>[answer.questionId,answer.selectedOptions]));draft.result=session.result;api.saveDraft(draft,this.__scope)}this.enterSession(session,draft);await this.loadQuestion(draft.index||0);return true}catch(error){if(!this.__disposed&&generation===this.__operationRequest)this.setData({error:errorText(error),authRequired:Number(error?.statusCode)===401,status:''});return false}finally{if(!this.__disposed&&generation===this.__operationRequest)this.setData({busy:false})}
 },
 resume(){return this.__recent?this.restoreSession(this.__recent.sessionId):false},
 reviewHistory(event){const id=publicParam(event.currentTarget?.dataset?.id);return id?this.restoreSession(id):false},
 cacheQuestion(question){this.__cache.delete(question.id);this.__cache.set(question.id,question);while(this.__cache.size>5)this.__cache.delete(this.__cache.keys().next().value)},
 async loadQuestion(index){
  if(!this.__session||!Number.isInteger(index)||index<0||index>=this.__session.questionIds.length)return false;const request=++this.__questionRequest,id=this.__session.questionIds[index];this.__targetIndex=index;this.setData({index,questionLoading:true,question:null,error:''})
  try{let question=this.__cache.get(id);if(!question){question=await api.fetchQuestion(id);if(question.routeId!==this.__session.routeId||this.__session.topicId&&!question.topicIds.includes(this.__session.topicId))throw Error('题目与当前练习范围不匹配。');this.cacheQuestion(question)}if(this.__disposed||request!==this.__questionRequest||!this.active())return false;this.__draft.index=index;api.saveDraft(this.__draft,this.__scope);this.renderQuestion(question,index);wx.pageScrollTo?.({scrollTop:0,duration:0});return true}catch(error){if(!this.__disposed&&request===this.__questionRequest)this.setData({error:errorText(error)});return false}finally{if(!this.__disposed&&request===this.__questionRequest)this.setData({questionLoading:false})}
 },
 retryQuestion(){return!this.data.busy&&this.__session?this.loadQuestion(Number.isInteger(this.__targetIndex)?this.__targetIndex:this.data.index):false},
 renderQuestion(question,index){const selected=this.__draft.answers[question.id]||[],item=this.__draft.result?.items?.find(value=>value.questionId===question.id)||null;this.setData({index,question:{...question,sourceLabel:sourceLabel(question,this.__catalog?.routes.find(route=>route.id===question.routeId)),options:question.options.map(value=>({value,selected:selected.includes(value)})),source:{...question.source,regions:question.source.regions.map(region=>({...region,loaded:false,failed:false}))}},selectedOptions:selected.slice(),selectionCount:selected.length,answeredCount:answered(this.__draft),currentResult:item})},
 toggleOption(event){if(this.data.busy||this.__draft?.status==='submitted'||!this.data.question)return;const option=publicParam(event.currentTarget?.dataset?.option,2),raw=this.data.question.options.map(item=>item.value);if(!raw.includes(option))return;const selected=this.data.question.answerMode==='single'?[option]:this.data.selectedOptions.includes(option)?this.data.selectedOptions.filter(value=>value!==option):raw.filter(value=>value===option||this.data.selectedOptions.includes(value)),next={...this.__draft,answers:{...this.__draft.answers},submissionId:''};if(selected.length)next.answers[this.data.question.id]=selected;else delete next.answers[this.data.question.id];try{this.__draft=api.saveDraft(next,this.__scope);this.setData({selectedOptions:selected,selectionCount:selected.length,answeredCount:answered(this.__draft),question:{...this.data.question,options:this.data.question.options.map(item=>({...item,selected:selected.includes(item.value)}))},status:'答案已保存到本机',error:''})}catch(error){this.setData({error:errorText(error),status:'答案尚未保存'})}},
 previous(){return this.data.index>0&&!this.data.busy?this.loadQuestion(this.data.index-1):false},
 next(){return this.data.index+1<this.data.total&&!this.data.busy?this.loadQuestion(this.data.index+1):false},
 async confirmIncomplete(missing){return new Promise(resolve=>wx.showModal({title:'仍有未作答题目',content:`还有 ${missing} 题未作答。确认后这些题按未作答计分，是否提交？`,confirmText:'确认提交',cancelText:'继续作答',success:result=>resolve(result.confirm===true),fail:()=>resolve(false)}))},
 async submit(){
  if(this.data.busy||!this.__draft||this.__draft.status==='submitted')return false;const done=answered(this.__draft);if(!done){this.setData({error:'请至少完成一题后再提交。'});return false}const missing=this.__draft.questionIds.length-done;if(missing&&!await this.confirmIncomplete(missing))return false
  if(!this.__draft.submissionId){this.__draft.submissionId=api.newSubmissionId();this.__draft=api.saveDraft(this.__draft,this.__scope)}const submissionId=this.__draft.submissionId,answers=this.__draft.questionIds.filter(id=>this.__draft.answers[id]?.length).map(id=>({questionId:id,selectedOptions:this.__draft.answers[id].slice()})),request=++this.__operationRequest;this.setData({busy:true,error:'',status:'正在提交学习结果…'})
  try{const response=await api.submitSession(this.__session.id,{submissionId,answers,...(missing?{confirmUnanswered:true}:{}),routeId:this.__session.routeId,questionIds:this.__session.questionIds},this.__scope);if(this.__disposed||request!==this.__operationRequest||!this.active())return false;this.__session=response.session;this.__draft.status='submitted';this.__draft.answers=Object.fromEntries(response.session.answers.filter(answer=>!answer.unanswered).map(answer=>[answer.questionId,answer.selectedOptions]));this.__draft.result=response.session.result;this.__draft=api.saveDraft(this.__draft,this.__scope);this.setData({phase:'result',result:response.session.result,status:response.duplicate?'已恢复同一次提交结果':'学习结果已保存',error:'',answeredCount:answered(this.__draft)});const question=this.__cache.get(this.__session.questionIds[this.data.index]);if(question)this.renderQuestion(question,this.data.index);return true}catch(error){if(!this.__disposed&&request===this.__operationRequest)this.setData({error:errorText(error),authRequired:Number(error?.statusCode)===401,status:'答案已保留，可重试提交'});return false}finally{if(!this.__disposed&&request===this.__operationRequest)this.setData({busy:false})}
 },
 setImageState(event,state){const id=publicParam(event.currentTarget?.dataset?.id);if(!this.data.question?.source.regions.some(item=>item.assetId===id))return;this.setData({question:{...this.data.question,source:{...this.data.question.source,regions:this.data.question.source.regions.map(item=>item.assetId===id?{...item,...state}:item)}}})},
 imageLoaded(event){this.setImageState(event,{loaded:true,failed:false})},imageFailed(event){this.setImageState(event,{loaded:false,failed:true})},
 retryImage(event){const item=this.data.question?.source.regions.find(value=>value.assetId===event.currentTarget?.dataset?.id);if(!item)return;this.setImageState(event,{imageUrl:'',loaded:false,failed:false});wx.nextTick?.(()=>{if(!this.__disposed)this.setImageState(event,{imageUrl:item.imageUrl})})},
 previewImage(event){const item=this.data.question?.source.regions.find(value=>value.assetId===event.currentTarget?.dataset?.id),urls=this.data.question?.source.regions.map(value=>value.imageUrl).filter(Boolean)||[];if(item?.imageUrl)wx.previewImage({current:item.imageUrl,urls})},
 openAccount(){wx.navigateTo({url:'/bundles/account/auth'})},backToLibrary(){wx.navigateBack({fail:()=>wx.redirectTo({url:'/bundles/curricula/index?board=ap'})})},
 onShareAppMessage(){const query=[['routeId',this.data.routeId],['topicId',this.data.topicId]].filter(([,value])=>value).map(([key,value])=>key+'='+encodeURIComponent(publicParam(value))).join('&');return{title:'STEMist · AP 选择题练习',path:'/bundles/curricula/practice'+(query?'?'+query:''),imageUrl:'/design-system/share-card.png'}},
})
